#
# check_widget_classification.sh — issue-20261115 §6.4 plan A
#
# `docs/plans/widget_classification.md` is generated by
# `tools/gen_widget_classification.py` from `src/widget/kind.rs`, the capability tables and
# `src/widget/mod.rs`. This gate fails when the committed page drifts from that derivation, so
# the family membership, the kind/control totals and the per-family module gate cannot go stale
# the way the scanned §6 table did.
#
# Usage: tools/check_widget_classification.sh

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"
. "$ROOT_DIR/tools/lib_python.sh"

STATUS=0
OUTPUT="$("$PYTHON" tools/gen_widget_classification.py --check)" || STATUS=$?
printf '%s\n' "$OUTPUT"
[[ "$STATUS" -eq 0 ]] || exit "$STATUS"
echo "check_widget_classification: OK"
